# PS6 data: the daily growth rates of SPY and its stocks, the GICS sector of each stock, and the
# levels of the FRED series. Students do not edit this file.
#
# The file has two functions:
#   1. load_universe      builds the real market from the course package VLQuantitativeFinancePackage
#   2. load_fred_levels   reads the levels of the FRED series from data/fred-levels-2014-2024.csv
#
# The code calls the real market the universe: the NamedTuple that load_universe returns. Every other
# part of PS6 starts from it. GICS, the Global Industry Classification Standard, puts each company in one
# of 11 sectors, such as Energy or Utilities.

# The location of the FRED file, built from the folder of this file: @__DIR__ is the src folder, and ".."
# goes up one folder, to the PS6 folder -
const FRED_LEVELS_PATH = joinpath(@__DIR__, "..", "data", "fred-levels-2014-2024.csv");

"""
    load_universe(settings::NamedTuple) -> NamedTuple

Load the market: SPY and every stock with the full 2014 to 2024 price history and a GICS sector,
one ticker per firm. This is the universe of the L14a example 'A Synthetic Market of Many Stocks'.

### Arguments

- `settings`: The settings from `load_config`. The function uses `benchmark_ticker` and `Δt`.

### Returns

- A `NamedTuple` with the fields:
  - `tickers`: The tickers of the stocks, in alphabetical order.
  - `sectors`: The GICS sector of each stock.
  - `sector_names`: The sectors, in alphabetical order.
  - `G`: The daily growth rates of the stocks (1/yr), days × stocks.
  - `g_m`: The daily growth rates of SPY (1/yr).
"""
function load_universe(settings::NamedTuple)::NamedTuple

    # Load the daily prices from 2014 to 2024, and the GICS sector table, from the course package.
    # dataset is a Dict: each key is a ticker, and each value is a table of that ticker's daily prices.
    # sector_table has one row per S&P 500 company -
    dataset = MyTrainingMarketDataSet()["dataset"];
    sector_table = MySP500SectorDataSet();

    # Build two lookups from the sector table: sector_of[ticker] gives the GICS sector of a ticker, and
    # firm_of[ticker] gives its company, as a CIK number. A company with two classes of shares, such as
    # Alphabet (GOOG and GOOGL), has one CIK number and two tickers. eachrow visits the table one row at a
    # time, and row."GICS Sector" reads the column whose name has a space -
    sector_of = Dict{String,String}();
    firm_of = Dict{String,Int}();
    for row ∈ eachrow(sector_table)
        sector_of[row.Symbol] = row."GICS Sector";
        firm_of[row.Symbol] = row.CIK;
    end

    # Keep every stock with the full price history and a sector, one ticker per firm. SPY has a price on
    # every trading day, so a stock has the full history when it has as many prices as SPY.
    # sort(collect(keys(dataset))) lists the tickers in alphabetical order, so the stocks always come in
    # the same order -
    number_of_prices = nrow(dataset[settings.benchmark_ticker]);
    tickers = String[];
    firms_seen = Int[];
    for ticker ∈ sort(collect(keys(dataset)))

        # A ticker qualifies when it is not SPY, has a sector, and has as many prices as SPY -
        is_stock = ticker != settings.benchmark_ticker;
        has_sector = haskey(sector_of, ticker);
        has_history = nrow(dataset[ticker]) == number_of_prices;
        if is_stock && has_sector && has_history

            # Keep the first ticker of each firm, and skip the firm's other tickers. firms_seen lists
            # the CIK numbers of the firms kept so far -
            if !(firm_of[ticker] in firms_seen)
                push!(tickers, ticker);
                push!(firms_seen, firm_of[ticker]);
            end
        end
    end

    # The sector of each stock, in the order of the tickers, and the list of the sectors that appear, in
    # alphabetical order. unique removes the repeated sectors -
    sectors = String[];
    for ticker ∈ tickers
        push!(sectors, sector_of[ticker]);
    end
    sector_names = sort(unique(sectors));

    # The growth rates of SPY and of each stock (1/yr), from the daily closing prices. With rf = 0.0,
    # excess_growth_rates gives the growth rate log(S(t) / S(t-1)) / Δt of each day, as in the course
    # examples. G has one row per day after the first, and column i holds stock i -
    g_m = JumpHMM.excess_growth_rates(Vector{Float64}(dataset[settings.benchmark_ticker].close);
        rf = 0.0, Δt = settings.Δt);
    G = zeros(number_of_prices - 1, length(tickers));
    for i ∈ 1:length(tickers)
        G[:, i] = JumpHMM.excess_growth_rates(Vector{Float64}(dataset[tickers[i]].close);
            rf = 0.0, Δt = settings.Δt);
    end

    # Return the market by name. fit_factor_model reads universe.G and universe.g_m, sector_matrix reads
    # universe.sectors and universe.sector_names, and the report reads universe.sectors -
    return (tickers = tickers, sectors = sectors, sector_names = sector_names, G = G, g_m = g_m);
end

"""
    load_fred_levels(settings::NamedTuple) -> Matrix{Float64}

Load the level of each FRED series in `settings.fred_series` on each SPY price day.

### Arguments

- `settings`: The settings from `load_config`. The function uses `fred_series`.

### Returns

- The levels, price days × series, with the columns in the order of `settings.fred_series`.
"""
function load_fred_levels(settings::NamedTuple)::Matrix{Float64}

    # Read the FRED file into a table: one row per SPY price day, and one column per FRED series, named
    # by its FRED code, such as DGS10 -
    table = CSV.read(FRED_LEVELS_PATH, DataFrame);

    # Copy the column of each series in settings.fred_series, in that order. table[:, name] reads every
    # row of the column with that name -
    number_of_series = length(settings.fred_series);
    levels = zeros(nrow(table), number_of_series);
    for k ∈ 1:number_of_series
        levels[:, k] = table[:, settings.fred_series[k]];
    end
    return levels;
end
